import os,re
tot=0; per={}
for dp,_,fns in os.walk('AlgebraicJacobian'):
    for fn in fns:
        if not fn.endswith('.lean'): continue
        p=os.path.join(dp,fn); s=open(p,encoding='utf-8',errors='replace').read()
        # strip block comments then line comments
        s2=re.sub(r'/-.*?-/', '', s, flags=re.S)
