python3 - <<'PY'
import os, re, collections, json
root='AlgebraicJacobian'
mods={}
for dp,dn,fn in os.walk(root):
    for f in fn:
        if f.endswith('.lean'):
            p=os.path.join(dp,f)
            m=p[:-5].replace('/','.')
            mods[m]=p
print("total modules under AlgebraicJacobian/:",len(mods))
imp=re.compile(r'^\s*import\s+([A-Za-z0-9_.]+)')
graph={}
for m,p in mods.items():
    ims=[]
    for line in open(p,encoding='utf-8',errors='replace'):
        mm=imp.match(line)
        if mm: ims.append(mm.group(1))
    graph[m]=ims
# closure restricted to in-tree modules (external mathlib ignored)
import sys
sys.setrecursionlimit(100000)
memo={}
def clo(m,stack=()):
    if m in memo: return memo[m]
    s=set([m])
    for d in graph.get(m,[]):
        if d in graph and d not in stack:
            s |= clo(d, stack+(m,))
    memo[m]=s
    return s
for m in graph: clo(m)
# root file
rootfile='AlgebraicJacobian.lean'
rootims=[]
for line in open(rootfile,encoding='utf-8',errors='replace'):
    mm=imp.match(line)
    if mm: rootims.append(mm.group(1))
rooted=set()
for d in rootims:
    if d in graph: rooted |= memo[d]
print("root aggregator direct imports (in-tree):",len([d for d in rootims if d in graph]),"of",len(rootims))
print("rooted (transitively reachable from AlgebraicJacobian.lean):",len(rooted))
un=sorted(set(graph)-rooted)
print("unrooted:",len(un))
for u in un: print("   ",u)
json.dump({m:sorted(memo[m]) for m in memo}, open('/tmp/ajcr_closure.json','w'))
PY
